-- =====================================================================
-- V1__baseline.sql — Kazi global schema baseline
-- Phase 86 squash. Generated by dump-and-clean of a fresh database migrated with the full
-- pre-squash series (Flyway 11.14.1, PostgreSQL 16) at commit a99b11f50 (main, 2026-10-18),
-- post-removal; proven equal to the public + portal schemas of the test database by
-- BaselineSchemaParityTest.
-- Supersedes global V1..V29 (25 files + 4 Phase 86 drop migrations V26..V29),
-- archived at git tag `horizontal-platform-final`.
-- RULE: this file is immutable once the first production tenant exists.
--       Never squash again; add V2+ feature migrations. See backend/db/BASELINE.md.
-- Hand-cleaned: no pg_dump noise, deterministic order, all chk_/uq_/idx_/fk_ names preserved.
-- =====================================================================

CREATE EXTENSION IF NOT EXISTS pg_trgm;

CREATE SCHEMA IF NOT EXISTS portal;

-- ---------------------------------------------------------------------
-- Tables (FK-dependency order; constraints inline)
-- ---------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS access_requests (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    email character varying(255) NOT NULL,
    full_name character varying(200) NOT NULL,
    organization_name character varying(200) NOT NULL,
    country character varying(100) NOT NULL,
    industry character varying(100) NOT NULL,
    status character varying(20) DEFAULT 'PENDING_VERIFICATION'::character varying NOT NULL,
    otp_hash character varying(255),
    otp_expires_at timestamp with time zone,
    otp_attempts integer DEFAULT 0 NOT NULL,
    otp_verified_at timestamp with time zone,
    reviewed_by character varying(255),
    reviewed_at timestamp with time zone,
    keycloak_org_id character varying(255),
    provisioning_error text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT access_requests_pkey PRIMARY KEY (id)
);

CREATE TABLE IF NOT EXISTS job_queue (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    job_type character varying(100) NOT NULL,
    tenant_id character varying(50) NOT NULL,
    org_id character varying(100) NOT NULL,
    shard_id character varying(50) DEFAULT 'primary'::character varying NOT NULL,
    status character varying(20) DEFAULT 'PENDING'::character varying NOT NULL,
    payload jsonb,
    priority integer DEFAULT 0 NOT NULL,
    claimed_by character varying(100),
    claimed_at timestamp with time zone,
    completed_at timestamp with time zone,
    retry_count integer DEFAULT 0 NOT NULL,
    max_retries integer DEFAULT 3 NOT NULL,
    next_attempt_at timestamp with time zone DEFAULT now() NOT NULL,
    error_message text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT chk_job_queue_non_negative CHECK (((retry_count >= 0) AND (max_retries >= 0))),
    CONSTRAINT chk_job_status CHECK ((status IN ('PENDING', 'CLAIMED', 'COMPLETED', 'FAILED', 'DEAD_LETTER'))),
    CONSTRAINT job_queue_pkey PRIMARY KEY (id)
);

CREATE TABLE IF NOT EXISTS organizations (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    external_org_id character varying(255) NOT NULL,
    name character varying(255) NOT NULL,
    provisioning_status character varying(50) DEFAULT 'PENDING'::character varying NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT organizations_clerk_org_id_key UNIQUE (external_org_id),
    CONSTRAINT organizations_pkey PRIMARY KEY (id)
);

CREATE TABLE IF NOT EXISTS portal.portal_acceptance_requests (
    id uuid NOT NULL,
    portal_contact_id uuid NOT NULL,
    generated_document_id uuid NOT NULL,
    document_title character varying(500) NOT NULL,
    document_file_name character varying(500) NOT NULL,
    status character varying(20) NOT NULL,
    request_token character varying(255) NOT NULL,
    sent_at timestamp with time zone,
    expires_at timestamp with time zone NOT NULL,
    org_name character varying(255) NOT NULL,
    org_logo character varying(500),
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT portal_acceptance_requests_pkey PRIMARY KEY (id)
);

CREATE TABLE IF NOT EXISTS portal.portal_comments (
    id uuid NOT NULL,
    org_id character varying(255) NOT NULL,
    portal_project_id uuid NOT NULL,
    author_name character varying(255) NOT NULL,
    content text NOT NULL,
    created_at timestamp without time zone NOT NULL,
    synced_at timestamp without time zone DEFAULT now() NOT NULL,
    CONSTRAINT portal_comments_pkey PRIMARY KEY (id)
);

CREATE TABLE IF NOT EXISTS portal.portal_deadline_view (
    id uuid NOT NULL,
    source_entity character varying(30) NOT NULL,
    customer_id uuid NOT NULL,
    matter_id uuid,
    deadline_type character varying(20) NOT NULL,
    label character varying(160) NOT NULL,
    due_date date NOT NULL,
    status character varying(20) NOT NULL,
    description_sanitised character varying(140),
    last_synced_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT portal_deadline_view_deadline_type_check CHECK ((deadline_type IN ('FILING', 'COURT_DATE', 'PRESCRIPTION', 'CUSTOM_DATE'))),
    CONSTRAINT portal_deadline_view_source_entity_check CHECK ((source_entity IN ('FILING_SCHEDULE', 'COURT_DATE', 'PRESCRIPTION_TRACKER', 'CUSTOM_FIELD_DATE'))),
    CONSTRAINT portal_deadline_view_status_check CHECK ((status IN ('UPCOMING', 'DUE_SOON', 'OVERDUE', 'COMPLETED', 'CANCELLED'))),
    CONSTRAINT portal_deadline_view_pkey PRIMARY KEY (source_entity, id)
);

CREATE TABLE IF NOT EXISTS portal.portal_documents (
    id uuid NOT NULL,
    org_id character varying(255) NOT NULL,
    customer_id uuid,
    portal_project_id uuid,
    title character varying(500) NOT NULL,
    content_type character varying(100),
    size bigint,
    scope character varying(20) NOT NULL,
    s3_key character varying(1000) NOT NULL,
    uploaded_at timestamp without time zone,
    synced_at timestamp without time zone DEFAULT now() NOT NULL,
    CONSTRAINT portal_documents_pkey PRIMARY KEY (id)
);

CREATE TABLE IF NOT EXISTS portal.portal_invoices (
    id uuid NOT NULL,
    org_id character varying(255) NOT NULL,
    customer_id uuid NOT NULL,
    invoice_number character varying(20) NOT NULL,
    status character varying(20) NOT NULL,
    issue_date date,
    due_date date,
    subtotal numeric(14,2) DEFAULT 0 NOT NULL,
    tax_amount numeric(14,2) DEFAULT 0 NOT NULL,
    total numeric(14,2) DEFAULT 0 NOT NULL,
    currency character varying(3) NOT NULL,
    notes text,
    synced_at timestamp without time zone DEFAULT now() NOT NULL,
    payment_url character varying(1024),
    payment_session_id character varying(255),
    paid_at timestamp with time zone,
    tax_breakdown_json jsonb,
    tax_registration_number character varying(50),
    tax_registration_label character varying(30),
    tax_label character varying(20),
    tax_inclusive boolean DEFAULT false NOT NULL,
    has_per_line_tax boolean DEFAULT false NOT NULL,
    CONSTRAINT portal_invoices_pkey PRIMARY KEY (id)
);

CREATE TABLE IF NOT EXISTS portal.portal_notification_preference (
    portal_contact_id uuid NOT NULL,
    digest_enabled boolean DEFAULT true NOT NULL,
    trust_activity_enabled boolean DEFAULT true NOT NULL,
    deadline_reminders_enabled boolean DEFAULT true NOT NULL,
    action_required_enabled boolean DEFAULT true NOT NULL,
    last_updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT portal_notification_preference_pkey PRIMARY KEY (portal_contact_id)
);

CREATE TABLE IF NOT EXISTS portal.portal_project_summaries (
    id uuid NOT NULL,
    org_id character varying(255) NOT NULL,
    customer_id uuid NOT NULL,
    total_hours numeric(10,2) DEFAULT 0 NOT NULL,
    billable_hours numeric(10,2) DEFAULT 0 NOT NULL,
    last_activity_at timestamp without time zone,
    synced_at timestamp without time zone DEFAULT now() NOT NULL,
    CONSTRAINT portal_project_summaries_pkey PRIMARY KEY (id, customer_id)
);

CREATE TABLE IF NOT EXISTS portal.portal_projects (
    id uuid NOT NULL,
    org_id character varying(255) NOT NULL,
    customer_id uuid NOT NULL,
    name character varying(255) NOT NULL,
    status character varying(50) NOT NULL,
    description text,
    document_count integer DEFAULT 0 NOT NULL,
    comment_count integer DEFAULT 0 NOT NULL,
    created_at timestamp without time zone NOT NULL,
    updated_at timestamp without time zone DEFAULT now() NOT NULL,
    CONSTRAINT portal_projects_pkey PRIMARY KEY (id, customer_id)
);

CREATE TABLE IF NOT EXISTS portal.portal_requests (
    id uuid NOT NULL,
    request_number character varying(20) NOT NULL,
    customer_id uuid NOT NULL,
    portal_contact_id uuid NOT NULL,
    project_id uuid,
    project_name character varying(300),
    org_id character varying(255) NOT NULL,
    status character varying(20) NOT NULL,
    total_items integer DEFAULT 0 NOT NULL,
    submitted_items integer DEFAULT 0 NOT NULL,
    accepted_items integer DEFAULT 0 NOT NULL,
    rejected_items integer DEFAULT 0 NOT NULL,
    sent_at timestamp with time zone,
    completed_at timestamp with time zone,
    synced_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT portal_requests_pkey PRIMARY KEY (id)
);

CREATE TABLE IF NOT EXISTS portal.portal_tasks (
    id uuid NOT NULL,
    org_id character varying(255) NOT NULL,
    portal_project_id uuid NOT NULL,
    name character varying(500) NOT NULL,
    status character varying(20) NOT NULL,
    assignee_name character varying(255),
    sort_order integer DEFAULT 0 NOT NULL,
    synced_at timestamp without time zone DEFAULT now() NOT NULL,
    CONSTRAINT portal_tasks_pkey PRIMARY KEY (id)
);

CREATE TABLE IF NOT EXISTS portal.portal_trust_balance (
    customer_id uuid NOT NULL,
    matter_id uuid NOT NULL,
    current_balance numeric(15,2) DEFAULT 0 NOT NULL,
    last_transaction_at timestamp with time zone,
    last_synced_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT portal_trust_balance_pkey PRIMARY KEY (customer_id, matter_id)
);

CREATE TABLE IF NOT EXISTS portal.portal_trust_transaction (
    id uuid NOT NULL,
    customer_id uuid NOT NULL,
    matter_id uuid NOT NULL,
    transaction_type character varying(20) NOT NULL,
    amount numeric(15,2) NOT NULL,
    running_balance numeric(15,2) NOT NULL,
    occurred_at timestamp with time zone NOT NULL,
    description character varying(140),
    reference character varying(100),
    last_synced_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT portal_trust_transaction_pkey PRIMARY KEY (id)
);

CREATE TABLE IF NOT EXISTS processed_webhooks (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    svix_id character varying(255) NOT NULL,
    event_type character varying(100) NOT NULL,
    processed_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT processed_webhooks_pkey PRIMARY KEY (id),
    CONSTRAINT processed_webhooks_svix_id_key UNIQUE (svix_id)
);

CREATE TABLE IF NOT EXISTS shard_config (
    shard_id character varying(50) NOT NULL,
    display_name character varying(100) NOT NULL,
    jdbc_url character varying(500),
    username character varying(100),
    pool_size integer DEFAULT 10 NOT NULL,
    read_only boolean DEFAULT false NOT NULL,
    active boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT shard_config_pkey PRIMARY KEY (shard_id)
);

CREATE TABLE IF NOT EXISTS shedlock (
    name character varying(64) NOT NULL,
    lock_until timestamp without time zone NOT NULL,
    locked_at timestamp without time zone NOT NULL,
    locked_by character varying(255) NOT NULL,
    CONSTRAINT shedlock_pkey PRIMARY KEY (name)
);

CREATE TABLE IF NOT EXISTS org_schema_mapping (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    external_org_id character varying(255) NOT NULL,
    schema_name character varying(255) NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    shard_id character varying(50) DEFAULT 'primary'::character varying NOT NULL,
    CONSTRAINT org_schema_mapping_clerk_org_id_key UNIQUE (external_org_id),
    CONSTRAINT org_schema_mapping_pkey PRIMARY KEY (id),
    CONSTRAINT fk_org_schema_mapping_shard FOREIGN KEY (shard_id) REFERENCES shard_config(shard_id)
);

CREATE TABLE IF NOT EXISTS portal.portal_invoice_lines (
    id uuid NOT NULL,
    portal_invoice_id uuid NOT NULL,
    description text NOT NULL,
    quantity numeric(10,4) NOT NULL,
    unit_price numeric(12,2) NOT NULL,
    amount numeric(14,2) NOT NULL,
    sort_order integer DEFAULT 0 NOT NULL,
    synced_at timestamp without time zone DEFAULT now() NOT NULL,
    tax_rate_name character varying(100),
    tax_rate_percent numeric(5,2),
    tax_amount numeric(14,2),
    tax_exempt boolean DEFAULT false NOT NULL,
    CONSTRAINT portal_invoice_lines_pkey PRIMARY KEY (id),
    CONSTRAINT portal_invoice_lines_portal_invoice_id_fkey FOREIGN KEY (portal_invoice_id) REFERENCES portal.portal_invoices(id) ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS portal.portal_request_items (
    id uuid NOT NULL,
    request_id uuid NOT NULL,
    name character varying(200) NOT NULL,
    description text,
    response_type character varying(20) NOT NULL,
    required boolean DEFAULT true NOT NULL,
    file_type_hints character varying(200),
    sort_order integer DEFAULT 0 NOT NULL,
    status character varying(20) DEFAULT 'PENDING'::character varying NOT NULL,
    rejection_reason character varying(500),
    document_id uuid,
    text_response text,
    synced_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT portal_request_items_pkey PRIMARY KEY (id),
    CONSTRAINT portal_request_items_request_id_fkey FOREIGN KEY (request_id) REFERENCES portal.portal_requests(id) ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS subscriptions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    current_period_start timestamp with time zone,
    current_period_end timestamp with time zone,
    cancelled_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    subscription_status character varying(30) NOT NULL,
    trial_ends_at timestamp with time zone,
    grace_ends_at timestamp with time zone,
    billing_method character varying(30) DEFAULT 'MANUAL'::character varying NOT NULL,
    admin_note text,
    CONSTRAINT subscriptions_organization_id_key UNIQUE (organization_id),
    CONSTRAINT subscriptions_pkey PRIMARY KEY (id),
    CONSTRAINT subscriptions_organization_id_fkey FOREIGN KEY (organization_id) REFERENCES organizations(id)
);

-- ---------------------------------------------------------------------
-- Indexes
-- ---------------------------------------------------------------------

CREATE INDEX IF NOT EXISTS idx_portal_acceptance_contact_status ON portal.portal_acceptance_requests USING btree (portal_contact_id, status);
CREATE INDEX IF NOT EXISTS idx_portal_acceptance_token ON portal.portal_acceptance_requests USING btree (request_token);
CREATE INDEX IF NOT EXISTS idx_portal_comments_project ON portal.portal_comments USING btree (portal_project_id);
CREATE INDEX IF NOT EXISTS idx_portal_deadline_customer_due ON portal.portal_deadline_view USING btree (customer_id, due_date);
CREATE INDEX IF NOT EXISTS idx_portal_documents_org_customer ON portal.portal_documents USING btree (org_id, customer_id);
CREATE INDEX IF NOT EXISTS idx_portal_documents_project ON portal.portal_documents USING btree (portal_project_id);
CREATE INDEX IF NOT EXISTS idx_portal_invoice_lines_invoice ON portal.portal_invoice_lines USING btree (portal_invoice_id);
CREATE INDEX IF NOT EXISTS idx_portal_invoices_customer_issue_date ON portal.portal_invoices USING btree (customer_id, issue_date DESC);
CREATE INDEX IF NOT EXISTS idx_portal_invoices_org_customer ON portal.portal_invoices USING btree (org_id, customer_id);
CREATE INDEX IF NOT EXISTS idx_portal_projects_org_customer ON portal.portal_projects USING btree (org_id, customer_id);
CREATE INDEX IF NOT EXISTS idx_portal_request_items_request ON portal.portal_request_items USING btree (request_id);
CREATE INDEX IF NOT EXISTS idx_portal_requests_contact ON portal.portal_requests USING btree (portal_contact_id);
CREATE INDEX IF NOT EXISTS idx_portal_requests_customer ON portal.portal_requests USING btree (customer_id, org_id);
CREATE INDEX IF NOT EXISTS idx_portal_requests_status ON portal.portal_requests USING btree (status);
CREATE INDEX IF NOT EXISTS idx_portal_tasks_org ON portal.portal_tasks USING btree (org_id);
CREATE INDEX IF NOT EXISTS idx_portal_tasks_project ON portal.portal_tasks USING btree (portal_project_id);
CREATE INDEX IF NOT EXISTS idx_portal_trust_txn_customer_matter_occurred ON portal.portal_trust_transaction USING btree (customer_id, matter_id, occurred_at DESC);
CREATE INDEX IF NOT EXISTS idx_access_requests_email ON access_requests USING btree (email);
CREATE UNIQUE INDEX IF NOT EXISTS idx_access_requests_email_pending ON access_requests USING btree (email) WHERE (status IN ('PENDING_VERIFICATION', 'PENDING'));
CREATE INDEX IF NOT EXISTS idx_access_requests_status ON access_requests USING btree (status);
CREATE INDEX IF NOT EXISTS idx_job_queue_claimable ON job_queue USING btree (priority DESC, next_attempt_at) WHERE ((status)::text = 'PENDING'::text);
CREATE UNIQUE INDEX IF NOT EXISTS idx_job_queue_dedup ON job_queue USING btree (job_type, tenant_id) WHERE (status IN ('PENDING', 'CLAIMED'));
CREATE INDEX IF NOT EXISTS idx_job_queue_stale_claims ON job_queue USING btree (claimed_at) WHERE ((status)::text = 'CLAIMED'::text);
CREATE INDEX IF NOT EXISTS idx_job_queue_status_type ON job_queue USING btree (job_type, status, created_at);
CREATE INDEX IF NOT EXISTS idx_org_schema_mapping_external_org_id ON org_schema_mapping USING btree (external_org_id);
CREATE INDEX IF NOT EXISTS idx_org_schema_mapping_shard ON org_schema_mapping USING btree (shard_id);
CREATE INDEX IF NOT EXISTS idx_organizations_external_org_id ON organizations USING btree (external_org_id);
CREATE INDEX IF NOT EXISTS idx_organizations_provisioning_status ON organizations USING btree (provisioning_status);
CREATE INDEX IF NOT EXISTS idx_processed_webhooks_svix_id ON processed_webhooks USING btree (svix_id);
CREATE INDEX IF NOT EXISTS idx_subscriptions_billing_method ON subscriptions USING btree (billing_method);
CREATE INDEX IF NOT EXISTS idx_subscriptions_organization_id ON subscriptions USING btree (organization_id);
CREATE INDEX IF NOT EXISTS idx_subscriptions_status ON subscriptions USING btree (subscription_status);

-- ---------------------------------------------------------------------
-- Migration-seeded rows
-- ---------------------------------------------------------------------

-- Stale-job recovery lock row (originally V24)
INSERT INTO shedlock (name, lock_until, locked_at, locked_by)
VALUES ('stale_job_recovery', NOW(), NOW(), 'migration')
ON CONFLICT (name) DO NOTHING;

-- Primary shard (originally V25)
INSERT INTO shard_config (shard_id, display_name)
VALUES ('primary', 'Primary Database')
ON CONFLICT (shard_id) DO NOTHING;
